@-moz-document domain("discord.com") {
/* Background: Jinwoo Cyberpunk Eyes */
  body {
    background-image: url("https://cdn.discordapp.com/attachments/1099961441004319744/1152992316148687963/jinwoo.webp"); /* https://www.bing.com/images/search?view=detailV2&ccid=UI%2b9wLY1&id=5C107AB13D9D6F598D9AF96A6E21B482703E24AF&thid=OIP.UI-9wLY1w5GXMRSeIFrxdgHaEK&mediaurl=https%3a%2f%2f4kwallpapers.com%2fimages%2fwallpapers%2fsung-jinwoo-dark-4480x2520-21604.jpg&cdnurl=https%3a%2f%2fth.bing.com%2fth%2fid%2fR.508fbdc0b635c3919731149e205af176%3frik%3dryQ%252bcIK0IW5q%252bQ%26pid%3dImgRaw%26r%3d0&exph=2520&expw=4480&q=blue+jinwoo+image&simid=608019425857270151&FORM=IRPRST&ck=28E77DE14338731790CC111AB2EF3ED6&selectedIndex=4&itb=0 */
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
  }

  /* Make main UI dark and translucent */
  .theme-dark, .appMount-3lHmkl {
    background: rgba(0, 0, 0, 0.8) !important;
  }

  /* Blue neon text and accent colors */
  .title-29uC1r, .name-3Vmqxm, .channelName-3KPsGw, .link-1_kTxV {
    color: #00b7ff !important;
    text-shadow: 0 0 5px #00b7ff;
  }

  /* Accent for selected/hovered items */
  .selected-1-Z6gm, .modeSelected-3DmyhH, .interactiveSelected-29CP8y {
    background-color: rgba(0, 183, 255, 0.2) !important;
    border-left: 3px solid #00b7ff !important;
  }

  /* Scrollbar styling */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #00b7ff;
    border-radius: 10px;
  }

  /* Chat background overlay */
  .chatContent-3KubbW {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }

  /* Sidebar background */
  .sidebar-1tnWFu {
    background-color: rgba(10, 10, 20, 0.7) !important;
  }

  /* User popout and modals */
  .userPopoutOuter-3AVBmJ, .root-8LYsGj {
    background: rgba(10, 10, 20, 0.85) !important;
    border: 1px solid #00b7ff;
  }

  /* Message text */
  .messageContent-2qWWxC {
    color: #dbefff !important;
  }

  /* Timestamp and minor text */
  .timestamp-3ZCmNB, .subtext-2HDqJ7 {
    color: #007799 !important;
  }
}
